#!/usr/bin/env bun
// @bun
var CINEMA_ID="0000000002";var BASE_URL="https://www.classiccinemas.com.au/api";var AEST_OFFSET_MS=10*60*60*1000;async function fetchJson(url,destPath){const resp=await fetch(url);if(!resp.ok){throw new Error(`GET ${url} failed: ${resp.status} ${resp.statusText}`)}const text=await resp.text();if(destPath){await Bun.write(destPath,text)}return JSON.parse(text)}async function readOrFetchJson(path,url){const file=Bun.file(path);if(await file.exists()){return JSON.parse(await file.text())}return fetchJson(url,path)}function seatmapTmpPath(sessionId){return`/tmp/cc-seatmap-${sessionId}.json`}function seatmapUrl(sessionId){return`${BASE_URL}/sessions/${CINEMA_ID}/${sessionId}/seating-map`}function formatTime(isoStr){const timePart=isoStr.split("T")[1]??"";const[hStr="0",mStr="0"]=timePart.split(":");let hours=Number.parseInt(hStr,10);const minutes=Number.parseInt(mStr,10);const ampm=hours>=12?"pm":"am";hours=hours%12;if(hours===0)hours=12;const mm=minutes.toString().padStart(2,"0");return`${hours}:${mm}${ampm}`}function todayAest(){const now=new Date;const local=new Date(now.getTime()+AEST_OFFSET_MS);return local.toISOString().slice(0,10)}function maybeExitWithHelp(arg,help){if(arg==="-h"||arg==="--help"){console.log(help);process.exit(0)}}function runMain(main){main().catch((err)=>{console.error(err instanceof Error?err.message:String(err));process.exit(1)})}var HELP=`classic-cinema list-movies \u2014 today's Elsternwick listing

Usage:
  bun run src/list-movies.ts [--movie QUERY]

Options:
  --movie QUERY   Fuzzy-match a movie name (substring, case-insensitive)
  -h, --help      Show this help

Output: one JSON object per line on stdout. Diagnostics on stderr.
Exit: 0 ok, 1 no sessions/no match, 64 invalid usage.`;function parseArgs(argv){let movie=null;for(let i=0;i<argv.length;i++){const arg=argv[i];maybeExitWithHelp(arg,HELP);if(arg==="--movie"){movie=argv[++i]??""}else if(arg.startsWith("--movie=")){movie=arg.slice("--movie=".length)}else{console.error(`Unknown argument: ${arg}`);console.error(HELP);process.exit(64)}}return{movie}}async function main(){const{movie}=parseArgs(process.argv.slice(2));const sessions=await fetchJson(`${BASE_URL}/sessions/${CINEMA_ID}`,"/tmp/cc-sessions.json");const movies=await fetchJson(`${BASE_URL}/movies`,"/tmp/cc-movies.json");const today=todayAest();const movieMap=new Map;for(const m of movies){if(m.vistaId)movieMap.set(m.vistaId,m)}const todaySessions=new Map;for(const s of sessions){if(s.date?.slice(0,10)!==today)continue;const mid=s.movieId;if(mid&&movieMap.has(mid)){const list=todaySessions.get(mid)??[];list.push(s);todaySessions.set(mid,list)}}if(todaySessions.size===0){console.error("No sessions showing today at Elsternwick");process.exit(1)}const earliest=(slist)=>slist.reduce((min,s)=>s.date<min?s.date:min,slist[0].date);const sorted=[...todaySessions.entries()].sort((a,b)=>earliest(a[1]).localeCompare(earliest(b[1])));let entries=sorted.map(([mid,slist])=>{const m=movieMap.get(mid);const sessList=[...slist].sort((a,b)=>a.date.localeCompare(b.date)).map((s)=>({id:s.id,time:formatTime(s.date),screen:s.screenName??"?",screenNumber:s.screenNumber??0,date:s.date}));const trailer=m.trailer??"";return{name:m.name,vistaId:mid,rating:m.rating?.id??"?",runtime:m.runtime??"?",trailer:trailer?`https://www.youtube.com/watch?v=${trailer}`:null,summary:m.summary??"",headerImage:m.headerImage??"",posterImage:m.posterImage??"",sessions:sessList}});if(movie){const query=movie.toLowerCase();const matched=entries.filter((e)=>e.name.toLowerCase().includes(query));if(matched.length===0){console.error(`No movies matching '${movie}' today`);entries.forEach((e,i)=>{console.error(`  ${i+1}. ${e.name}`)});process.exit(1)}entries=matched}entries.forEach((e,i)=>{e.index=i+1;console.log(JSON.stringify(e))})}if(import.meta.main){runMain(main)}
